import { test, expect } from "../helpers/system-control-browser";
import AxeBuilder from "@axe-core/playwright";

for (const route of ["/", "/pricing"]) {
  test(`Recommended badge stays inset and pricing follows all themes on ${route}`, async ({
    page,
  }, testInfo) => {
    test.setTimeout(120000);
    await page.emulateMedia({ reducedMotion: "reduce" });
    await page.goto(route);
    const cards = page.locator("[data-plan-cards]");
    const badge = cards.locator("[data-recommended-ribbon]");
    await expect(badge).toHaveText("★ Recommended");
    await expect(
      cards.locator('article[aria-label="Free plan"] li'),
    ).toHaveText([
      "1 editable template",
      "2 saved role shortcuts",
      "PDF attachment, 5 MB",
      "Gmail acceptance status",
      "Lavender & Nightbloom themes",
    ]);
    await expect(
      cards.locator('article[aria-label="Premium plan"] li'),
    ).toHaveText([
      "Edit recipient roles in Compose",
      "Follow-up reminders: 3, 7 or 14 days",
      "“Mark replied” tracking",
      "CSV import, up to 1,000 rows",
      "Unlimited templates & 8 role shortcuts",
      "Add to shortlist directly from History",
      "Manual repeat sends",
      "All four themes, including Chalk & Obsidian",
      "10 preview highlight colors",
      "Prioritized email support",
    ]);
    await expect(cards.locator('[data-highlighted="true"]')).toHaveCount(0);
    await expect(
      cards.locator('article[aria-label="Free plan"] [data-plan-badge]'),
    ).toHaveText("Free plan");
    await page.evaluate(() => document.fonts.ready);
    if (route === "/") {
      const light = page.getByRole("button", {
        name: "Switch to light theme",
        exact: true,
      });
      await light.click();
      await expect(
        page.getByRole("button", { name: "Switch to dark theme" }),
      ).toBeVisible();
    } else {
      await page.getByRole("button", { name: "Choose appearance" }).click();
      await expect(
        page.getByRole("menu", { name: "Appearance", exact: true }),
      ).toBeVisible();
      await page.keyboard.press("Escape");
    }
    for (const [appearance, theme, name] of [
      ["purple", "light", "lavender"],
      ["purple", "dark", "nightbloom"],
      ["vercel", "light", "chalk"],
      ["vercel", "dark", "obsidian"],
    ]) {
      await page.evaluate(
        ({ appearance, theme }) => {
          document.documentElement.dataset.appearance = appearance;
          document.documentElement.dataset.theme = theme;
        },
        { appearance, theme },
      );
      const cardBackgrounds = await cards.locator("article").evaluateAll((els) =>
        els.map((el) => getComputedStyle(el).backgroundImage),
      );
      expect(cardBackgrounds).toHaveLength(2);
      for (const background of cardBackgrounds) {
        expect(background).toContain("radial-gradient(");
        expect(background).toContain("linear-gradient(");
        if (name === "nightbloom")
          expect(background).toContain("rgb(20, 14, 41)");
      }
      if (!testInfo.project.name.includes("mobile")) {
        await page.setViewportSize({ width: 1440, height: 1000 });
        const tile = cards.locator("[data-upgrade-stat]").first();
        await tile.scrollIntoViewIfNeeded();
        await page.mouse.move(0, 0);
        const restingShadow = await tile.evaluate(
          (el) => getComputedStyle(el).boxShadow,
        );
        await tile.hover();
        await expect
          .poll(() => tile.evaluate((el) => getComputedStyle(el).boxShadow))
          .not.toBe(restingShadow);
        await page.mouse.move(0, 0);
        await expect(tile).toHaveCSS("box-shadow", restingShadow);
      }
      for (const width of [1440, 820, 700, 699, 390, 320]) {
        await page.setViewportSize({ width, height: 1000 });
        await badge.scrollIntoViewIfNeeded();
        expect(
          await badge.evaluate((el) => {
            const badge = el.getBoundingClientRect();
            const card = el.closest("article")!.getBoundingClientRect();
            const heading = el
              .closest("article")!
              .querySelector("h2, h3")!
              .getBoundingClientRect();
            return (
              badge.left >= card.left + 12 &&
              badge.right <= card.right - 12 &&
              badge.top < heading.bottom
            );
          }),
        ).toBe(true);
        expect(
          await page.evaluate(
            () => document.documentElement.scrollWidth <= innerWidth,
          ),
        ).toBe(true);
        expect(
          await cards.evaluate(
            (el) => getComputedStyle(el).gridTemplateColumns.split(" ").length,
          ),
        ).toBe(width >= 700 ? 2 : 1);
        const statContrast = await cards
          .locator("[data-upgrade-stat]")
          .evaluateAll((tiles) => {
            const luminance = (color: string) => {
              const channels = color
                .match(/[\d.]+/g)!
                .slice(0, 3)
                .map(Number)
                .map((value) => {
                  const channel = value / 255;
                  return channel <= 0.04045
                    ? channel / 12.92
                    : ((channel + 0.055) / 1.055) ** 2.4;
                });
              return (
                channels[0] * 0.2126 +
                channels[1] * 0.7152 +
                channels[2] * 0.0722
              );
            };
            const ratio = (foreground: string, background: string) => {
              const a = luminance(foreground),
                b = luminance(background);
              return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
            };
            return tiles.flatMap((tile) => {
              const background = getComputedStyle(tile).backgroundColor;
              const value = getComputedStyle(tile.querySelector("dt")!);
              const label = getComputedStyle(tile.querySelector("dd")!);
              const colors = value.backgroundImage.match(/rgb\([^)]+\)/g) ?? [
                value.color,
              ];
              return [
                ...colors.map((color) => ratio(color, background)),
                ratio(label.color, background),
              ];
            });
          });
        expect(statContrast.every((ratio) => ratio >= 4.5)).toBe(true);
        const freeBox = (await cards.locator("article").first().boundingBox())!;
        const premiumBox = (await cards
          .locator("article")
          .last()
          .boundingBox())!;
        if (width >= 700) {
          expect(freeBox.y).toBeCloseTo(premiumBox.y, 0);
          expect(premiumBox.width / freeBox.width).toBeCloseTo(1.15, 1);
          const actions = await cards
            .locator("article")
            .evaluateAll((els) =>
              els.map(
                (el) =>
                  el.querySelector("button, a")!.getBoundingClientRect().bottom,
              ),
            );
          expect(actions[0]).toBeCloseTo(actions[1], 0);
        } else
          expect(freeBox.y).toBeGreaterThan(premiumBox.y + premiumBox.height);
        expect(
          (
            await new AxeBuilder({ page })
              .include("[data-plan-cards]")
              .analyze()
          ).violations,
        ).toEqual([]);
        await cards.screenshot({
          path: testInfo.outputPath(`cards-${name}-${width}.png`),
        });
      }
    }
    const button = cards.locator("article").last().getByRole("button", {
      name: "Upgrade to Premium",
    });
    await page.keyboard.press("Tab");
    await button.focus();
    await expect(button).toBeFocused();
    expect(
      await button.evaluate((el) => getComputedStyle(el).outlineStyle),
    ).toBe("solid");
    await page.setViewportSize({ width: 1440, height: 1000 });
    await page.emulateMedia({ reducedMotion: "no-preference" });
    const card = cards.locator("article").last();
    await card.dispatchEvent("pointermove", {
      pointerType: "mouse",
      clientX: 200,
      clientY: 300,
    });
    const position = await card.evaluate((el) =>
      el.style.getPropertyValue("--spot-x"),
    );
    expect(position).not.toBe("");
    await page.emulateMedia({ reducedMotion: "reduce" });
    await card.dispatchEvent("pointermove", {
      pointerType: "mouse",
      clientX: 250,
      clientY: 350,
    });
    expect(
      await card.evaluate((el) => el.style.getPropertyValue("--spot-x")),
    ).toBe(position);
  });
}
